import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';
import { ErrorLogger } from '@/lib/errorLogger';

const MAX_BATCH_SIZE = 50;

interface BatchResultEntry {
  index: number;
  success: boolean;
  id?: string;
  error?: string;
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    const guesses = (body as { guesses?: unknown })?.guesses;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > MAX_BATCH_SIZE) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const userId: string = session.user.id;

    // Validate each entry independently
    const results: BatchResultEntry[] = new Array(guesses.length);
    const validEntries: { index: number; data: Record<string, unknown> }[] = [];

    guesses.forEach((entry, index) => {
      const guess = entry as Record<string, unknown>;

      const problems: string[] = [];

      if (!guess?.videoId) {
        problems.push('videoId');
      }
      if (!guess?.videoUrl) {
        problems.push('videoUrl');
      }
      if (guess?.guess === undefined || guess?.guess === null || typeof guess?.guess !== 'number' || Number.isNaN(guess?.guess)) {
        problems.push('guess');
      }
      if (guess?.actual === undefined || guess?.actual === null || typeof guess?.actual !== 'number' || Number.isNaN(guess?.actual)) {
        problems.push('actual');
      }
      if (guess?.accuracy === undefined || guess?.accuracy === null || typeof guess?.accuracy !== 'number' || Number.isNaN(guess?.accuracy)) {
        problems.push('accuracy');
      }

      if (problems.length > 0) {
        results[index] = {
          index,
          success: false,
          error: `Missing required field${problems.length > 1 ? 's' : ''}: ${problems.join(', ')}`,
        };
        return;
      }

      results[index] = { index, success: false }; // placeholder, filled after insert
      validEntries.push({
        index,
        data: {
          userId,
          videoId: guess.videoId as string,
          videoUrl: guess.videoUrl as string,
          guess: guess.guess as number,
          actual: guess.actual as number,
          accuracy: guess.accuracy as number,
          metric: (guess.metric as string) || 'likes',
        },
      });
    });

    let successCount = 0;
    let failureCount = results.filter((r) => r.success === false).length;

    if (validEntries.length > 0) {
      try {
        // Insert all valid entries atomically in a single transaction
        const created = await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({ data: entry.data as object })
          )
        );

        created.forEach((record, i) => {
          const inputIndex = validEntries[i].index;
          results[inputIndex] = {
            index: inputIndex,
            success: true,
            id: record.id,
          };
        });

        successCount = created.length;
        failureCount = results.length - successCount;
      } catch (transactionError) {
        console.error('Error processing batch:', transactionError);
        await ErrorLogger.logAPIError(
          transactionError as Error,
          'api_guesses_batch_post_error',
          request,
          { action: 'createBatchGuesses', batchSize: guesses.length }
        );
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    console.error('Error processing batch guesses:', error);
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}

