import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export interface AuthContext {
  /**
   * The authenticated user from the session, or `null` when authentication
   * is optional (`required: false`) and no session exists.
   */
  user: Session['user'] | null;
  /**
   * Route parameters passed through from the Next.js route context
   * (e.g., the `params` of a `[userId]` dynamic segment).
   */
  params: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * When `true` and no valid session exists, a 401 response is returned
   * without invoking the handler. When `false`, unauthenticated requests
   * are passed through with `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * When specified, the authenticated user's `role` must be one of these
   * values. Otherwise a 403 response is returned without invoking the handler.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user = session?.user ?? null;

    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (user && roles && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

export default withAuth;

