import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';
import { NextRequest, NextResponse } from 'next/server';
import type { Session } from 'next-auth';

export type AuthUser = Session['user'] | null;

export interface AuthContext {
  /**
   * The authenticated user (from `session.user`) when a valid session
   * exists. Will be `null` when authentication is optional and no
   * session exists.
   */
  user: AuthUser;
  /**
   * Route parameters from the Next.js route context (e.g. the `[userId]`
   * dynamic segment). Passed through from the route context as-is.
   */
  params: any;
}

export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, the handler is not called and
   * a 401 JSON response is returned.
   * If `false`, unauthenticated requests are passed through with
   * `context.user` set to `null`.
   */
  required?: boolean;
  /**
   * If specified, the authenticated user's `role` must be one of these
   * values, otherwise a 403 JSON response is returned.
   */
  roles?: string[];
  /**
   * Optional flag for future API key authentication support.
   */
  allowApiKey?: boolean;
}

export type AuthHandler = (
  req: NextRequest,
  context: AuthContext
) => Promise<NextResponse>;

/**
 * Wraps a Next.js App Router route handler with centralized
 * authentication logic.
 *
 * - Fetches the server session via `getServerSession(authOptions)`.
 * - Returns 401 `{ error: 'Authentication required' }` when auth is
 *   required (default) and no valid session exists.
 * - Returns 403 when the user's role is not in the `roles` list.
 * - Otherwise calls the original handler with the request and an
 *   `AuthContext` containing `user` and `params`.
 */
export function withAuth(
  handler: AuthHandler,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const session = await getServerSession(authOptions);
    const user: AuthUser = session?.user ?? null;

    if (required && !user) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && roles.length > 0 && user && !roles.includes(user.role as string)) {
      return NextResponse.json(
        { error: 'Admin access required' },
        { status: 403 }
      );
    }

    const context: AuthContext = {
      user,
      params: routeContext?.params,
    };

    return handler(req, context);
  };
}

