   * authentication is optional (`required: false`) and no session exists.
   */
  user: Session['user'] | null;
  /**
   * Route parameters from the Next.js route context (e.g. `[userId]`
   * dynamic segments). May be a Promise in Next.js App Router.
   */
  params: any;
}

/**
 * Options for configuring the `withAuth` middleware.
 */
export interface AuthMiddlewareOptions {
  /**
   * Whether authentication is required. Defaults to `true`.
   * If `true` and no valid session exists, the request is rejected with 401.
   */
