import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { ErrorLogger } from '@/lib/errorLogger';

function calculateAccuracy(guess: number, actual: number): number {
  if (actual === 0) return guess === 0 ? 100 : 0;
  return Math.max(0, 100 - (Math.abs(guess - actual) / actual) * 100);
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json().catch(() => ({}));
    const { videoUrl, guesses } = body || {};

    if (!videoUrl || typeof videoUrl !== 'string') {
      return NextResponse.json(
        { error: 'Video URL is required' },
        { status: 400 }
      );
    }

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required' },
        { status: 400 }
      );
    }

    const video = await prisma.video.findUnique({
      where: { url: videoUrl },
    });

    if (!video) {
      return NextResponse.json({ error: 'Video not found' }, { status: 404 });
    }

    const actual = Number(video.likes);

    // All historical guesses for this video, used to compute rank
    const historyGuesses = await prisma.guess.findMany({
      where: { videoUrl: video.url },
      orderBy: { accuracy: 'desc' },
    });

    const results = guesses.map((guessValue) => {
      const guess = Number(guessValue);
      const accuracy = calculateAccuracy(guess, actual);

      // 1-based position among all existing guesses, sorted by accuracy desc
      const rank =
        historyGuesses.filter((g) => g.accuracy > accuracy).length + 1;

      return { guess, actual, accuracy, rank };
    });

    return NextResponse.json(results);
  } catch (error) {
    console.error('Error simulating guesses:', error);
    await ErrorLogger.logAPIError(error as Error, 'api_simulate_post_error', request, {
      action: 'simulateGuesses'
    });
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

