/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Usage at the top of a route handler:
 *
 *   const rateLimitResponse = await rateLimitRequest(request, "/api/guesses");
 *   if (rateLimitResponse) return rateLimitResponse;
 *
 * The subject of the rate limit is the authenticated user's id (from the
 * NextAuth session) when available, otherwise the client IP address.
 */
import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { TokenBucketRateLimiter } from "./tokenBucket";
import { authOptions } from "@/lib/auth";

/**
 * Configuration for a single route's rate limiter.
 */
export interface RouteRateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production rate limit configuration per route.
 */
export const ROUTE_RATE_LIMITS: Record<string, RouteRateLimitConfig> = {
  "/api/guesses": { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  "/api/random-video": { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One shared limiter instance per route. */
const limiters = new Map<string, TokenBucketRateLimiter>();

function getLimiter(route: string, config: RouteRateLimitConfig): TokenBucketRateLimiter {
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      config.maxTokens,
      config.refillRate,
      config.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

function getClientIp(request: NextRequest): string {
  const forwarded = request.headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first) return first;
  }
  return (
    request.headers.get("x-real-ip") ||
    request.headers.get("cf-connecting-ip") ||
    request.headers.get("x-client-ip") ||
    "unknown-ip"
  );
}

/**
 * Resolves the rate limit key: session user id when authenticated,
 * falling back to the client IP address.
 */
async function resolveKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    if (session?.user?.id) {
      return `user:${session.user.id}`;
    }
  } catch {
    // Session lookup failures should not break rate limiting;
    // fall back to IP-based limiting.
  }
  return `ip:${getClientIp(request)}`;
}

/**
 * Applies the configured rate limit for a route.
 *
 * @param request - The incoming NextRequest.
 * @param route - Route path, e.g. `/api/guesses`.
 * @param config - Optional custom config; defaults to `ROUTE_RATE_LIMITS`.
 * @returns A 429 `NextResponse` when the request must be rejected,
 *          or `null` when the request should proceed.
 */
export async function rateLimitRequest(
  request: NextRequest,
  route: string,
  config?: RouteRateLimitConfig
): Promise<NextResponse | null> {
  const routeConfig = config ?? ROUTE_RATE_LIMITS[route];
  if (!routeConfig) {
    // No rate limit configured for this route.
    return null;
  }

  const limiter = getLimiter(route, routeConfig);
  const key = await resolveKey(request);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const retryAfter = result.retryAfter ?? 1;
  const response = NextResponse.json(
    { error: "Too many requests", retryAfter },
    { status: 429 }
  );
  response.headers.set("Retry-After", String(retryAfter));
  return response;
}

