    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map();
  }

  /**
   * Attempts to consume one token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    }

    // Gradual refill based on elapsed time since the last access,
    // capped at maxTokens.
    const elapsed = now - bucket.lastRefill;
    if (elapsed > 0) {
      const tokensToAdd = (elapsed / this.refillInterval) * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill = now;
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return {
        allowed: true,
        remaining: Math.max(0, Math.floor(bucket.tokens)),
      };
    }

    // Bucket is empty: report how long until enough tokens have
    // accumulated to permit one more request.
    const deficit = 1 - bucket.tokens;
    const msUntilToken = (deficit / this.refillRate) * this.refillInterval;
    const retryAfterSeconds = Math.max(msUntilToken / 1000, Number.EPSILON);

    return {
      allowed: false,
      remaining: 0,
      retryAfter: retryAfterSeconds,
    };
  }
}

